function validate([n, limit]) {
  if (!Number.isInteger(n) || n < 1 || n > 100000000) return 'n is an integer from 1 to 10^8.';
  if (!Number.isInteger(limit) || limit < 1 || limit > 100000000) return 'limit is an integer from 1 to 10^8.';
  return null;
}

