function distributeCandies(n, limit) {
  if (n > 3 * limit) {
    return 0;
  }
  const ways = (m) => (m < 0 ? 0 : ((m + 2) * (m + 1)) / 2);
  const choose = [1, 3, 3, 1];
  let total = 0;
  for (let over = 0; over <= 3; over++) {
    const sign = over % 2 === 0 ? 1 : -1;
    const rest = n - over * (limit + 1);
    total += sign * choose[over] * ways(rest);
  }
  return total;
}

