function distributeCandies(n, limit) {
  // Fix the first two children's shares; the third child takes the rest if it fits.
  let count = 0;
  for (let a = 0; a <= Math.min(n, limit); a++) {
    for (let b = 0; b <= Math.min(n - a, limit); b++) {
      if (n - a - b <= limit) count++;
    }
  }
  return count;
}

