function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = rand() < 0.2 ? 100000000 : pick(50000000, 100000000);
    const mode = rand();
    // The interesting range is limit between n / 3 (one way left) and n (no cap bites).
    const limit = mode < 0.15 ? 100000000 : mode < 0.3 ? Math.max(1, Math.floor(n / 3) - pick(0, 2)) : pick(Math.ceil(n / 3), Math.min(n, 100000000));
    return [n, limit];
  }
  const n = pick(1, 40);
  const limit = rand() < 0.2 ? pick(1, 60) : pick(1, Math.max(1, Math.ceil(n / 2) + 3));
  return [n, limit];
}
